/**
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = function(nums, target) {
    const mp = new Map(); // value -> index
    for (let i = 0; i < nums.length; ++i) {
        const need = target - nums[i];
        if (mp.has(need)) {
            return [mp.get(need), i];
        }
        mp.set(nums[i], i);
    }
    return [];
};
